25	/**
26	 * Options for constructing an {@link AgentSideEffects} instance.
27	 */
28	export interface IAgentSideEffectsOptions {
29		/** Resolve the agent responsible for a given session URI. */
30		readonly getAgent: (session: ProtocolURI) => IAgent | undefined;
31		/** Observable set of registered agents. Triggers `root/agentsChanged` when it changes. */
32		readonly agents: IObservable<readonly IAgent[]>;
33		/** Session data service for cleaning up per-session data on disposal. */
34		readonly sessionDataService: ISessionDataService;
