33	/** Default capacity of the server-side action replay buffer. */
34	const REPLAY_BUFFER_CAPACITY = 1000;
35	
36	/** Build a JSON-RPC success response suitable for transport.send(). */
37	function jsonRpcSuccess(id: number, result: unknown): IJsonRpcResponse {
38		return { jsonrpc: '2.0', id, result };
39	}
40	
41	/** Build a JSON-RPC error response suitable for transport.send(). */
42	function jsonRpcError(id: number, code: number, message: string, data?: unknown): IJsonRpcResponse {
43		return { jsonrpc: '2.0', id, error: { code, message, ...(data !== undefined ? { data } : {}) } };
44	}
45	
46	/** Build a JSON-RPC error response from an unknown thrown value, preserving {@link ProtocolError} fields. */
47	function jsonRpcErrorFrom(id: number, err: unknown): IJsonRpcResponse {
48		if (err instanceof ProtocolError) {
49			return jsonRpcError(id, err.code, err.message, err.data);
50		}
51		const message = err instanceof Error ? (err.stack ?? err.message) : String(err);
52		return jsonRpcError(id, JSON_RPC_INTERNAL_ERROR, message);
53	}
