55	/**
56	 * Methods handled by the request dispatcher. Excludes `initialize` and
57	 * `reconnect` which are handled during the handshake phase.
58	 */
59	type RequestMethod = Exclude<keyof ICommandMap, 'initialize' | 'reconnect' | 'authenticate'>;
60	
61	/**
62	 * Typed handler map: each key is a request method, each value is a handler
63	 * that receives the correctly-typed params and must return the correctly-typed
64	 * result. The compiler will error if a handler returns the wrong shape.
65	 */
66	type RequestHandlerMap = {
67		[M in RequestMethod]: (client: IConnectedClient, params: ICommandMap[M]['params']) => Promise<ICommandMap[M]['result']>;
68	};
