70	/**
71	 * Represents a connected protocol client with its subscription state.
72	 */
73	interface IConnectedClient {
74		readonly clientId: string;
75		readonly protocolVersion: number;
76		readonly transport: IProtocolTransport;
77		readonly subscriptions: Set<string>;
78		readonly disposables: DisposableStore;
79	}
