32	interface IPendingCall {
33		resolve: (result: unknown) => void;
34		reject: (err: Error) => void;
35	}
36	
37	class TestProtocolClient {
38		private readonly _ws: WebSocket;
39		private _nextId = 1;
40		private readonly _pendingCalls = new Map<number, IPendingCall>();
41		private readonly _notifications: IAhpNotification[] = [];
42		private readonly _notifWaiters: { predicate: (n: IAhpNotification) => boolean; resolve: (n: IAhpNotification) => void; reject: (err: Error) => void }[] = [];
43	
44		constructor(port: number) {
45			this._ws = new WebSocket(`ws://127.0.0.1:${port}`);
46		}
47	
48		async connect(): Promise<void> {
49			return new Promise<void>((resolve, reject) => {
50				this._ws.on('open', () => {
51					this._ws.on('message', (data: Buffer | string) => {
52						const text = typeof data === 'string' ? data : data.toString('utf-8');
53						const msg = JSON.parse(text);
54						this._handleMessage(msg);
55					});
56					resolve();
57				});
58				this._ws.on('error', reject);
59			});
60		}
61	
62		private _handleMessage(msg: IProtocolMessage): void {
63			if (isJsonRpcResponse(msg)) {
64				// JSON-RPC response — resolve pending call
65				const pending = this._pendingCalls.get(msg.id);
66				if (pending) {
67					this._pendingCalls.delete(msg.id);
68					const errResp = msg as IJsonRpcErrorResponse;
69					if (errResp.error) {
70						pending.reject(new Error(errResp.error.message));
71					} else {
72						pending.resolve((msg as IJsonRpcSuccessResponse).result);
73					}
74				}
75			} else if (isJsonRpcNotification(msg)) {
76				// JSON-RPC notification from server
77				const notif = msg;
78				// Check waiters first
79				for (let i = this._notifWaiters.length - 1; i >= 0; i--) {
80					if (this._notifWaiters[i].predicate(notif)) {
81						const waiter = this._notifWaiters.splice(i, 1)[0];
82						waiter.resolve(notif);
83					}
84				}
85				this._notifications.push(notif);
86			}
87		}
88	
89		/** Send a JSON-RPC notification (fire-and-forget). */
90		notify(method: string, params?: unknown): void {
91			this._ws.send(JSON.stringify({ jsonrpc: '2.0', method, params }));
92		}
93	
94		/** Send a JSON-RPC request and await the response. */
95		call<T>(method: string, params?: unknown, timeoutMs = 5000): Promise<T> {
96			const id = this._nextId++;
97			this._ws.send(JSON.stringify({ jsonrpc: '2.0', id, method, params }));
98	
99			return new Promise<T>((resolve, reject) => {
100				const timer = setTimeout(() => {
101					this._pendingCalls.delete(id);
102					reject(new Error(`Timeout waiting for response to ${method} (id=${id}, ${timeoutMs}ms)`));
103				}, timeoutMs);
104	
105				this._pendingCalls.set(id, {
106					resolve: result => { clearTimeout(timer); resolve(result as T); },
107					reject: err => { clearTimeout(timer); reject(err); },
108				});
109			});
110		}
111	
112		/** Wait for a server notification matching a predicate. */
113		waitForNotification(predicate: (n: IAhpNotification) => boolean, timeoutMs = 5000): Promise<IAhpNotification> {
114			const existing = this._notifications.find(predicate);
115			if (existing) {
116				return Promise.resolve(existing);
117			}
118	
119			return new Promise<IAhpNotification>((resolve, reject) => {
120				const timer = setTimeout(() => {
121					const idx = this._notifWaiters.findIndex(w => w.resolve === resolve);
122					if (idx >= 0) {
123						this._notifWaiters.splice(idx, 1);
124					}
125					reject(new Error(`Timeout waiting for notification (${timeoutMs}ms)`));
126				}, timeoutMs);
127	
128				this._notifWaiters.push({
129					predicate,
130					resolve: n => { clearTimeout(timer); resolve(n); },
131					reject,
132				});
133			});
134		}
135	
136		/** Return all received notifications matching a predicate. */
137		receivedNotifications(predicate?: (n: IAhpNotification) => boolean): IAhpNotification[] {
138			return predicate ? this._notifications.filter(predicate) : [...this._notifications];
139		}
140	
141		/** Send a raw string over the WebSocket without JSON serialization. */
142		sendRaw(data: string): void {
143			this._ws.send(data);
144		}
145	
146		/** Wait for the next raw message from the server. */
